'use strict'
// A CommonJS package whose export is a function carrying properties.
function createDebug(ns) {
  const log = (msg) => `${createDebug.prefix}${ns}: ${msg}`
  log.namespace = ns
  log.enabled = createDebug.enabled
  return log
}
createDebug.prefix = '> '
createDebug.enabled = true
createDebug.names = []
module.exports = createDebug
